<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\CareerOpening; use App\Models\CareerSetting; use Illuminate\Http\Request;
class CareerController extends Controller { public function edit(){return view('admin.careers',['settings'=>CareerSetting::firstOrCreate(['id'=>1]),'openings'=>CareerOpening::latest()->get()]);} public function update(Request $r){$d=$r->validate(['attorney_overview'=>'nullable|string','attorney_advancement'=>'nullable|string','staff_overview'=>'nullable|string','staff_advancement'=>'nullable|string','application_email'=>'nullable|email']);CareerSetting::updateOrCreate(['id'=>1],$d);return back()->with('success','Career content saved.');} public function store(Request $r){CareerOpening::create($r->validate(['track'=>'required|in:attorneys,professional-staff','title'=>'required|string|max:160','location'=>'required|string|max:160','description'=>'nullable|string']));return back()->with('success','Opening added.');} public function openingEdit(CareerOpening $opening){return view('admin.career-opening-edit',compact('opening'));} public function openingUpdate(Request $r,CareerOpening $opening){$opening->update($r->validate(['track'=>'required|in:attorneys,professional-staff','title'=>'required|string|max:160','location'=>'required|string|max:160','description'=>'nullable|string','active'=>'nullable|boolean']));return redirect()->route('admin.careers.edit')->with('success','Opening updated.');} public function destroy(CareerOpening $opening){$opening->delete();return back()->with('success','Opening deleted.');}}
